{"path":"test_chip8.js","content":"const fs = require('fs');
const html = fs.readFileSync('chip8_zai-glm-5.3_01.html', 'utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
if (!m) { console.log('NO SCRIPT'); process.exit(1); }
const src = m[1];

// DOM stubs
const ctx = { fillStyle: '', fillRect() {}, clearRect() {} };
const els = {};
function mkEl() {
  return { getContext: () => ctx, addEventListener() {}, textContent: '', innerHTML: '',
           value: '10', files: [], style: {}, className: '' };
}
global.document = { getElementById: id => els[id] || (els[id] = mkEl()), addEventListener() {} };
global.window = global;
global.requestAnimationFrame = () => {};
global.FileReader = function () {};

try {
  eval(src);
} catch (e) {
  console.log('EVAL ERROR:', e.message);
  console.log(e.stack.split('\n').slice(0, 4).join('\n'));
  process.exit(1);
}

// Reference interpreter state via globals created by eval (var/function go to global)
console.log('reset ok, pc =', cpu.pc.toString(16), '(expect 200)');

// delay timer decrement
cpu.dt = 5; cpu.st = 3;
if (typeof tickTimers === 'function') tickTimers();
console.log('timers after tick: dt =', cpu.dt, 'st =', cpu.st, '(expect 4, 2)');

// font loaded at 0x050?
console.log('font[0x050] =', memory[0x50].toString(2), '(expect 11110000)');

// run demo ROM headless
let pixelsDrawn = 0;
const origDraw = typeof drawScreen === 'function' ? drawScreen : null;
for (let f = 0; f < 120; f++) {
  for (let i = 0; i < 10; i++) step();
  if (typeof tickTimers === 'function') tickTimers();
}
let on = 0;
for (let y = 0; y < 32; y++) for (let x = 0; x < 64; x++) if (display[y * 64 + x]) on++;
console.log('after 120 frames: pc =', cpu.pc.toString(16), 'lit pixels =', on);
console.log(on > 0 ? 'DEMO RENDERS OK' : 'DEMO SHOWS NOTHING — BUG');

// opcode coverage: check dispatch handles all high nibbles / common cases without throw
// force-execute one of each major opcode class
try {
  const tests = [
    [0x00E0, 'CLS'], [0x00EE, 'RET'], [0x1222, 'JP'], [0x2222, 'CALL'], [0x3FFF, 'SE Vx'],
    [0x4FFF, 'SNE Vx'], [0x5FF0, 'SE Vy'], [0x6F11, 'LD Vx'], [0x7F11, 'ADD Vx'],
    [0x8FF0, 'LD Vy'], [0x8FF1, 'OR'], [0x8FF2, 'AND'], [0x8FF3, 'XOR'], [0x8FF4, 'ADD Vy'],
    [0x8FF5, 'SUB'], [0x8FF6, 'SHR'], [0x8FF7, 'SUBN'], [0x8FFE, 'SHL'],
    [0x9FF0, 'SNE Vy'], [0xA222, 'LD I'], [0xB222, 'JP V0'], [0xCFFF, 'RND'],
    [0xDFF5, 'DRW'], [0xEF9E, 'SKP'], [0xEFA1, 'SKNP'], [0xFF07, 'LD Vx DT'],
    [0xFF0A, 'LD Vx K'], [0xFF15, 'LD DT Vx'], [0xFF18, 'LD ST Vx'],
    [0xFF1E, 'ADD I Vx'], [0xFF29, 'LD F Vx'], [0xFF33, 'BCD'], [0xFF55, 'LD [I] Vx'],
    [0xFF65, 'LD Vx [I]']
  ];
  const savedPc = cpu.pc, savedStack = cpu.stack.slice(), savedSp = cpu.sp;
  for (const [op, name] of tests) {
    memory[0x300] = (op >> 8) & 0xFF; memory[0x301] = op & 0xFF;
    cpu.pc = 0x300;
    step(); // executes op, pc advances to 0x302
    if (cpu.pc !== 0x302 && op !== 0x00EE && op !== 0x1222 && op !== 0x2222 && op !== 0xB222)
      console.log('WARN pc not advanced for', name.toString(16), name, 'pc=', cpu.pc.toString(16));
    cpu.stack = savedStack.slice(); cpu.sp = savedSp;
  }
  cpu.pc = savedPc;
  console.log('ALL 35 OPCODE CLASSES EXECUTED WITHOUT THROW');
} catch (e) {
  console.log('OPCODE TEST THROW:', e.message);
  process.exit(1);
}
console.log('ALL CHECKS DONE');
"}

